// machines/plaits: the SHARC+ kernel of RINGS' resonator bank (lib/resonator.c, resonator_svf4_band_pass_add: the
// coefficients of four band-pass SVFs and their sample loop), GENERATED by lib/gen_resonator_svf4.py from its modulo
// schedule; edit the generator.
//
// void resonator_svf4_kernel(ResonatorSvf4 *s, const float *f, const float *q, const float *gain, const float *in,
//                            float *out, int size)
// resonator_svf4_band_pass_add's arguments and selcc's calling convention (R4 = s, R8 = f, R12 = q; gain, in, out
// and size at I6 + 1 .. 4; frame by CJUMP; return through I12 = DM(-1, I6) with RFRAME), for even sizes 4..16 (the
// caller checks). Output: bit-identical to the C function (see the generator's docstring).
//
// State on return (tests/plaits/test_resonator_kernel.py compares every register before and after): changed are the C
// ABI's scratch registers R0-R8, R12, I4, I12, LCNTR and the flags (ASTATx/y, STKYx/y: PEy's flags too, as in stock
// SIMD code; no stock code reads ASTATy/STKYy outside the interrupt and task save/restore, OPTIMIZING.md); every other
// register is as on entry: R9-R11, R13-R15, S0-S15 (saved and restored in SIMD pairs), M4, M6, I0, I1, L0, L1, L4
// (saved on the C stack above I7, so an interrupt push cannot reach them; M6 = 1 and L0 = L1 = L4 = 0 are set here,
// not assumed), MODE1 (PEYEN set for the kernel, cleared on the way out: the C caller runs in SISD), MODE2, the loop,
// PC and status stacks (two DO loops, both run to their end), I6, I7 (RFRAME) and the B registers. Assumes MODE1.RND32
// = 1 (32-bit float rounding, set at boot, 0x1c0f82): with 40-bit rounding the register-held states would differ from
// the C, which stores them each sample. Instruction forms: all occur in stock 1.17 DSP code; no PM transfers.

.SECTION/PM seg_pmco;
.GLOBAL resonator_svf4_kernel.;
.NOCOMPRESS;

resonator_svf4_kernel.:
    R0 = M4;                                            // SISD: the DAG registers it uses or relies on, through R0
                                                                // (a DAG1 register stored through DAG1 is illegal, PRM p.14-15)
    DM(I7, M7) = R0;
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;                                                     // its own values: no reliance on the caller's
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I7=MODIFY (I7,-34)(NW);                                   // the coefficient and tmp area [I7 + 1, I7 + 34]
    I4 = I7;
    I4=MODIFY (I4,1)(NW);                                     // its base: coefficients at I4 + 0..15
    I7=MODIFY (I7,-32)(NW);                                   // the pair area [I7 + 1, I7 + 32]
    BIT SET MODE1 0x200000;                                     // PEYEN: SIMD
    NOP;
    DM(1, I7) = R0;
    DM(3, I7) = R1;
    DM(5, I7) = R2;
    DM(7, I7) = R3;
    DM(9, I7) = R4;
    DM(11, I7) = R5;
    DM(13, I7) = R6;
    DM(15, I7) = R7;
    DM(17, I7) = R8;
    DM(19, I7) = R9;
    DM(21, I7) = R10;
    DM(23, I7) = R11;
    DM(25, I7) = R12;
    DM(27, I7) = R13;
    DM(29, I7) = R14;
    DM(31, I7) = R15;
    // ---- the coefficients of the four filters, two pairs (resonator.c's setup loop)
    I0 = R8;                                                    // f
    I1 = R12;                                                   // q
    R4 = 0x4121BA8F;                                            // 10.1080465f
    R5 = 0x425F2649;                                            // 55.7873878f
    R0 = DM(0, I0);                                             // f[0], f[1]
    R2 = DM(2, I0);                                             // f[2], f[3]
    R1 = DM(0, I1);                                             // q[0], q[1]
    R3 = DM(2, I1);                                             // q[2], q[3]
    I1 = DM(1, I6);                                             // gain
    R6 = 0x40490FDB;                                            // 3.14159274f
    R7 = 0x40000000;                                            // 2.0f
    R8 = 0x3F800000;                                            // 1.0f
    R9 = DM(0, I1);
    R10 = DM(2, I1);
    DM(12, I4) = R9;
    DM(14, I4) = R10;
    F9 = F0 * F0;                                             // tan_fast: f2
    F10 = F5 * F9;
    F10 = F4 + F10;
    F10 = F9 * F10;
    F10 = F6 + F10;
    F11 = F0 * F10;                                             // g
    DM(0, I4) = R11;
.COMPRESS;                                                      // RECIPS: stock uses only the short form
    F9 = RECIPS F1;                                             // r = 1 / q
.NOCOMPRESS;
    F10 = F1 * F9;
    F10 = F7 - F10;
    F9 = F9 * F10;
    F10 = F1 * F9;
    F10 = F7 - F10;
    F9 = F9 * F10;
    F12 = F8 * F9;
    F10 = F1 * F12;
    F10 = F8 - F10;
    F10 = F10 * F9;
    F12 = F12 + F10;                                            // r
    F10 = F12 * F11;                                            // d = 1 + r g + g g
    F10 = F8 + F10;
    F13 = F11 * F11;
    F10 = F10 + F13;
.COMPRESS;
    F9 = RECIPS F10;                                            // h = 1 / d
.NOCOMPRESS;
    F13 = F10 * F9;
    F13 = F7 - F13;
    F9 = F9 * F13;
    F13 = F10 * F9;
    F13 = F7 - F13;
    F9 = F9 * F13;
    F14 = F8 * F9;
    F13 = F10 * F14;
    F13 = F8 - F13;
    F13 = F13 * F9;
    F14 = F14 + F13;                                            // h
    F15 = F12 + F11, DM(8, I4) = R14;                          // r + g
    DM(4, I4) = R15;
    F9 = F2 * F2;                                             // tan_fast: f2
    F10 = F5 * F9;
    F10 = F4 + F10;
    F10 = F9 * F10;
    F10 = F6 + F10;
    F11 = F2 * F10;                                             // g
    DM(2, I4) = R11;
.COMPRESS;                                                      // RECIPS: stock uses only the short form
    F9 = RECIPS F3;                                             // r = 1 / q
.NOCOMPRESS;
    F10 = F3 * F9;
    F10 = F7 - F10;
    F9 = F9 * F10;
    F10 = F3 * F9;
    F10 = F7 - F10;
    F9 = F9 * F10;
    F12 = F8 * F9;
    F10 = F3 * F12;
    F10 = F8 - F10;
    F10 = F10 * F9;
    F12 = F12 + F10;                                            // r
    F10 = F12 * F11;                                            // d = 1 + r g + g g
    F10 = F8 + F10;
    F13 = F11 * F11;
    F10 = F10 + F13;
.COMPRESS;
    F9 = RECIPS F10;                                            // h = 1 / d
.NOCOMPRESS;
    F13 = F10 * F9;
    F13 = F7 - F13;
    F9 = F9 * F13;
    F13 = F10 * F9;
    F13 = F7 - F13;
    F9 = F9 * F13;
    F14 = F8 * F9;
    F13 = F10 * F14;
    F13 = F8 - F13;
    F13 = F13 * F9;
    F14 = F14 + F13;                                            // h
    F15 = F12 + F11, DM(10, I4) = R14;                          // r + g
    DM(6, I4) = R15;
    // ---- the sample loop's set-up
    I1 = DM(9, I7);                                             // s: R4 on entry (pair 4's PEx half)
    I0 = DM(2, I6);                                             // in: M4 = DM(I0, M6) (no PEy half)
    R0 = DM(4, I6);                                             // size
    R1 = 2;
    R0 = R0 - R1;
    I12 = R0;                                                   // the loop's trip count: size - 2
    R7 = 0;                                                    // 0.0f in both PEs: s_out's start
    R2 = DM(0, I1);                                             // s1A
    R3 = DM(2, I1);                                             // s1B
    R15 = DM(4, I1);                                            // s2A
    R14 = DM(6, I1);                                            // s2B
    I1 = I4;
    I1=MODIFY (I1,16)(NW);                                  // tmp: s_out per sample (PEx half)
    // ---- prologue: windows 0 and 1 of the modulo schedule
    M4 = DM(I0, M6);                                            // ldM4
    R10 = M4;                                                   // bcast
    R5 = DM(6, I4);                                             // ld_rpgB
    F12 = F3 * F5;                                              // m1B
    R5 = DM(8, I4);                                             // m1B ld_hA
    F11 = F10 - F12;                                            // a1B
    R4 = DM(4, I4);                                             // ld_rpgA
    F12 = F2 * F4;                                              // m1A
    F10 = F10 - F12, R4 = DM(10, I4);                           // a1A ld_hB
    F1 = F11 - F14;                                             // a2B
    F1 = F1 * F4;                                               // hpB
    R6 = DM(2, I4);                                             // hpB ld_gB
    F9 = F1 * F6, F0 = F10 - F15, M4 = DM(I0, M6);              // ldM4 a2A m2B
    F1 = F9 + F3;                                               // bpB
    F11 = F1 * F6;                                              // m3B
    R6 = DM(0, I4);                                             // m3B ld_gA
    R10 = M4;                                                   // bcast
    F3 = F9 + F1;                                               // s1B
    F0 = F0 * F5, F12 = F11 + F14, R5 = DM(6, I4);              // ld_rpgB lpB hpA
    F12 = F3 * F5, F14 = F11 + F12, R5 = DM(8, I4);             // m1B ld_hA s2B
    F12 = F0 * F6, F11 = F10 - F12;                             // a1B m2A
    F0 = F12 + F2, R4 = DM(4, I4);                              // ld_rpgA bpA
    F9 = F0 * F6;                                               // m3A
    R6 = DM(12, I4);                                            // m3A ld_gainA
    F2 = F12 + F0;                                              // s1A
    F12 = F2 * F4, F13 = F9 + F15, R4 = DM(14, I4);             // m1A lpA ld_gainB
    // ---- the loop: windows 2 .. size - 1, one sample each
    LCNTR = I12, DO (PC, _rsk_loop_end) UNTIL LCE;
    F8 = F1 * F4, F10 = F10 - F12, R4 = DM(10, I4);             // a1A ld_hB pB
    F12 = F0 * F6, F1 = F11 - F14;                              // a2B pA
    F11 = F7 + F12, R12 = S12;                                  // c1 swA
    F1 = F1 * F4, F15 = F9 + F13, R6 = DM(2, I4);               // hpB ld_gB s2A
    F9 = F1 * F6, F0 = F10 - F15, M4 = DM(I0, M6);              // ldM4 a2A m2B
    F1 = F9 + F3;                                               // bpB
    F11 = F1 * F6, F12 = F11 + F12, R6 = DM(0, I4);             // m3B ld_gA c2
    F13 = F12 + F8, R10 = M4;                                   // bcast c3
    F3 = F9 + F1, R8 = S8;                                      // s1B swB
    F0 = F0 * F5, F12 = F11 + F14, R5 = DM(6, I4);              // ld_rpgB lpB hpA
    F12 = F3 * F5, F14 = F11 + F12, R5 = DM(8, I4);             // m1B ld_hA s2B
    F12 = F0 * F6, F11 = F10 - F12;                             // a1B m2A
    F0 = F12 + F2, R4 = DM(4, I4);                              // ld_rpgA bpA
    F9 = F0 * F6, F8 = F8 + F13, R6 = DM(12, I4);               // m3A ld_gainA c4
    F2 = F12 + F0, DM(I1, M6) = R8;                             // s1A stc4
_rsk_loop_end:
    F12 = F2 * F4, F13 = F9 + F15, R4 = DM(14, I4);             // m1A lpA ld_gainB
    // ---- epilogue: windows size and size + 1
    F8 = F1 * F4, F10 = F10 - F12, R4 = DM(10, I4);             // a1A ld_hB pB
    F12 = F0 * F6, F1 = F11 - F14;                              // a2B pA
    F11 = F7 + F12, R12 = S12;                                  // c1 swA
    F1 = F1 * F4, F15 = F9 + F13, R6 = DM(2, I4);               // hpB ld_gB s2A
    F9 = F1 * F6;                                               // m2B
    F0 = F10 - F15;                                             // a2A m2B
    F1 = F9 + F3;                                               // bpB
    F11 = F1 * F6, F12 = F11 + F12, R6 = DM(0, I4);             // m3B ld_gA c2
    F13 = F12 + F8;                                             // c3
    F3 = F9 + F1, R8 = S8;                                      // s1B swB
    F0 = F0 * F5, F12 = F11 + F14;                              // lpB hpA
    F14 = F11 + F12;                                            // s2B
    F12 = F0 * F6;                                              // m2A
    F0 = F12 + F2;                                              // bpA
    F9 = F0 * F6, F8 = F8 + F13, R6 = DM(12, I4);               // m3A ld_gainA c4
    F2 = F12 + F0, DM(I1, M6) = R8;                             // s1A stc4
    F13 = F9 + F15, R4 = DM(14, I4);                            // lpA ld_gainB
    F8 = F1 * F4;                                               // pB
    F12 = F0 * F6;                                              // pA
    F11 = F7 + F12, R12 = S12;                                  // c1 swA
    F15 = F9 + F13;                                             // s2A
    F12 = F11 + F12;                                            // c2
    F13 = F12 + F8;                                             // c3
    R8 = S8;                                                    // swB
    F8 = F13 + F8;                                              // c4
    DM(I1, M6) = R8;                                            // stc4
    // ---- the states back, then out[n] += tmp[n] two samples per pass (the C loop's last addition)
    I0 = DM(9, I7);                                             // s
    I1 = I4;
    I1=MODIFY (I1,16)(NW);
    DM(0, I0) = R2;                                             // s1A
    DM(2, I0) = R3;                                             // s1B
    DM(4, I0) = R15;                                            // s2A
    DM(6, I0) = R14;                                            // s2B
    R2 = DM(4, I6);                                             // size
    I0 = DM(3, I6);                                             // out, loads
    I4 = DM(3, I6);                                             // out, stores
    M4 = 2;
    R3 = -2;
    R2 = R2 + R3;
    R3 = -1;
    R2 = LSHIFT R2 BY R3;                                       // size / 2 - 1: passes after the first
    R8 = DM(I0, M4);
    R12 = DM(I1, M4);
    LCNTR = R2, DO (PC, _rsk_add_end) UNTIL LCE;
    F10 = F8 + F12, R8 = DM(I0, M4);
    R12 = DM(I1, M4);
_rsk_add_end:
    DM(I4, M4) = R10;
    F10 = F8 + F12;
    DM(I4, M4) = R10;
    // ---- restore and return
    R0 = DM(1, I7);
    R1 = DM(3, I7);
    R2 = DM(5, I7);
    R3 = DM(7, I7);
    R4 = DM(9, I7);
    R5 = DM(11, I7);
    R6 = DM(13, I7);
    R7 = DM(15, I7);
    R8 = DM(17, I7);
    R9 = DM(19, I7);
    R10 = DM(21, I7);
    R11 = DM(23, I7);
    R12 = DM(25, I7);
    R13 = DM(27, I7);
    R14 = DM(29, I7);
    R15 = DM(31, I7);
    BIT CLR MODE1 0x200000;                                     // SISD again
    NOP;
    I7=MODIFY (I7,66)(NW);                                 // back to the seven pushes
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    M4 = DM(7, I7);
// selcc's own return sequence, compressed: under .NOCOMPRESS Selache encodes the indirect jump as Type 9a with
// the wrong registers and RFRAME as a NOP (PORTING.md drift 1)
.COMPRESS;
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
.NOCOMPRESS;
